import { change, type Change } from '../doc/log'
import { fragment, getNode, type Doc, type Key } from '../doc/model'
import type { Op } from '../doc/patch'
import { principals } from '../doc/resources'
import vocabularies from '../lookup/vocabularies.json'
import guidance from './guidance.json'
import overrides from './guidance-overrides.json'
import resourceTypes from './resource-types.json'

/**
 * Guidance: what kind of resource a record is, and which fields matter for
 * that kind, from how LC describes it (docs/guidance.md). guidance.json holds
 * the measurements, regenerated by scripts/guidance; guidance-overrides.json
 * the hand corrections and thresholds; resource-types.json how to tell the
 * kinds apart, which the sampler reads too.
 */

export interface ResourceType {
  id: string
  label: string
  /** "maps", for "used in 85% of maps". */
  plural: string
}

export type Resource = 'Instance' | 'Work'
export type Tier = 'shown' | 'suggested' | 'available'

export interface Usage {
  tier: Tier
  /** The share of this kind's records that use the property, 0 to 1. */
  share: number
  /** The resource LC puts it on more often, where a new value would go. */
  resource: Resource
  /** Set when an override put the property in its tier: the tier its share alone gives, and why. */
  override?: { measured: Tier; reason: string }
}

/** A hand correction for one kind: this property goes in this tier, whatever its share. */
export interface Override {
  prop: string
  tier: Tier
  reason: string
}

interface Rule extends ResourceType {
  work?: string[]
  issuance?: string[]
  online?: boolean
  start: Start
}

/** What a new record of a kind is written with: the types, and the issuance and carrier that define it. */
interface Start {
  work: string
  instance?: string
  issuance?: string
  carrier?: string
}

interface Measured {
  share: number
  /** For a property whose values are typed nodes, the share using each kind: identifiedBy Isbn. */
  kinds?: Record<string, number>
  /** For a linked property, its commonest values. */
  values?: { uri: string; share: number }[]
}

const rules: Rule[] = resourceTypes.types
const measured = guidance.types as unknown as Record<string, Record<Resource, Record<string, Measured>>>
const thresholds = overrides.thresholds
const never = new Set<string>(overrides.never)
const forced = overrides.types as Record<string, Override[]>

/**
 * The kind of resource a record is, by the same rules the sample was drawn
 * with: the Work's types and the Instance's issuance, and for an online kind,
 * an online resource as its only carrier. Undefined when no rule matches, or
 * the record has no Work yet.
 */
export function resourceTypeOf(doc: Doc): ResourceType | undefined {
  const { instance, work } = principals(doc)
  const workTypes = new Set(work ? typesOf(doc, work).map(localName) : [])
  const issuance = new Set(linksOf(doc, instance, 'issuance'))
  const carriers = new Set(linksOf(doc, instance, 'carrier'))
  const online = carriers.size === 1 && carriers.has('cr')
  const rule = rules.find(
    (rule) =>
      (rule.work?.some((type) => workTypes.has(type)) || rule.issuance?.some((code) => issuance.has(code))) &&
      (!rule.online || online),
  )
  return rule && { id: rule.id, label: rule.label, plural: rule.plural }
}

/** Every kind of resource guidance knows, in the order the rules try them. */
export const kinds: ResourceType[] = rules.map(({ id, label, plural }) => ({ id, label, plural }))

/**
 * Make a new record the given kind, as one change: the Work's and Instance's
 * types, and the issuance and carrier the kind is defined by (a serial's
 * issuance, an online resource as carrier). Only what an earlier kind wrote
 * is taken away, so nothing the cataloger entered is lost. Null when the
 * record is that kind already.
 */
export function kindChange(doc: Doc, id: string): Change | null {
  const rule = rules.find((candidate) => candidate.id === id)
  const { instance, work } = principals(doc)
  if (!rule || !work || resourceTypeOf(doc)?.id === id) return null
  const start = rule.start
  const starts = rules.map((candidate) => candidate.start)
  const ops: Op[] = [
    ...retype(doc, work, new Set(rules.flatMap((candidate) => [...(candidate.work ?? []), candidate.start.work])), start.work),
    ...retype(doc, instance, new Set(starts.flatMap((s) => (s.instance ? [s.instance] : []))), start.instance),
    ...relink(doc, instance, 'issuance', new Set(starts.flatMap((s) => (s.issuance ? [s.issuance] : []))), start.issuance),
    ...relink(doc, instance, 'carrier', new Set(starts.flatMap((s) => (s.carrier ? [s.carrier] : []))), start.carrier),
  ]
  return { ...change(`Made the record a ${rule.label.toLowerCase()}`, ops), kind: id }
}

/** What made a kind look likely: a field the record has, or its content type. */
export type Evidence = { prop: string } | { content: string; label: string }

export interface Inferred {
  kind: ResourceType
  because: Evidence[]
}

/** A kind and its online counterpart are one family: serial and serial-online. */
const family = (id: string) => id.replace(/-online$/, '')

/**
 * What tells a family of kinds apart, from the measurements: the fields most
 * of its records have (30% or more) and almost no unrelated record does (under
 * 5%), such as a map's scale, and the content type nearly all of them have
 * (90% or more) and other families almost never do, such as cartographic image.
 */
const signals: Map<string, { props: Set<string>; content: Set<string> }> = (() => {
  const shareOf = (type: string, prop: string) =>
    Math.max(measured[type]?.Instance[prop]?.share ?? 0, measured[type]?.Work[prop]?.share ?? 0)
  const contentOf = (type: string) =>
    [...(measured[type]?.Work.content?.values ?? []), ...(measured[type]?.Instance.content?.values ?? [])].map(
      (value) => ({ code: localName(value.uri), share: value.share }),
    )
  const types = Object.keys(measured)
  const result = new Map<string, { props: Set<string>; content: Set<string> }>()
  for (const type of types) {
    const unrelated = types.filter((other) => family(other) !== family(type))
    const entry = result.get(family(type)) ?? { props: new Set<string>(), content: new Set<string>() }
    const kind = measured[type]
    if (!kind) continue
    for (const prop of new Set([...Object.keys(kind.Instance), ...Object.keys(kind.Work)])) {
      if (never.has(prop) || shareOf(type, prop) < 0.3) continue
      if (unrelated.every((other) => shareOf(other, prop) < 0.05)) entry.props.add(prop)
    }
    for (const { code, share } of contentOf(type)) {
      if (share < 0.9) continue
      const elsewhere = unrelated.some((other) => contentOf(other).some((value) => value.code === code && value.share >= 0.05))
      if (!elsewhere) entry.content.add(code)
    }
    result.set(family(type), entry)
  }
  return result
})()

/**
 * The kind a record's values point to, where it isn't the kind the record is:
 * a "book" with a scale, or with cartographic image as its content type, looks
 * like a map. The family with the most signals wins; an online record is
 * offered the online kind of it, where there is one. Undefined when nothing
 * points elsewhere.
 */
export function inferredKind(doc: Doc): Inferred | undefined {
  const { instance, work } = principals(doc)
  const resources = work ? [instance, work] : [instance]
  const props = new Set(resources.flatMap((key) => Object.keys(getNode(doc, key).props)))
  const content = new Set(resources.flatMap((key) => linksOf(doc, key, 'content')))
  let best: { family: string; because: Evidence[] } | undefined
  for (const [name, signal] of signals) {
    const because: Evidence[] = [
      ...[...signal.content].filter((code) => content.has(code)).map((code) => ({ content: code, label: contentLabel(code) })),
      ...[...signal.props].filter((prop) => props.has(prop)).map((prop) => ({ prop })),
    ]
    if (because.length > (best?.because.length ?? 0)) best = { family: name, because }
  }
  const current = resourceTypeOf(doc)
  if (!best || (current && family(current.id) === best.family)) return undefined
  const carriers = linksOf(doc, instance, 'carrier')
  const online = carriers.length === 1 && carriers[0] === 'cr'
  const id = online && rules.some((rule) => rule.id === `${best.family}-online`) ? `${best.family}-online` : best.family
  const kind = kinds.find((candidate) => candidate.id === id)
  return kind && { kind, because: best.because }
}

function contentLabel(code: string): string {
  return vocabularies.contentTypes.find((entry) => localName(entry.uri) === code)?.label ?? code
}

/** Swap a node's kind-defining type for another, keeping its other types. */
function retype(doc: Doc, key: Key, kinds: Set<string>, to: string | undefined): Op[] {
  const from = getNode(doc, key).keywords['@type']
  const types = typesOf(doc, key)
  const next = [...types.filter((type) => !kinds.has(type)), ...(to ? [to] : [])]
  return next.join() === types.join() ? [] : [{ op: 'keyword', node: key, name: '@type', from, to: next }]
}

/** Swap a kind-defining linked value (serl, cr) for another, leaving any the cataloger chose. */
function relink(doc: Doc, key: Key, prop: string, codes: Set<string>, to: string | undefined): Op[] {
  const values = getNode(doc, key).props[prop] ?? []
  const ops: Op[] = []
  let has = false
  for (const value of values) {
    const id = 'node' in value ? getNode(doc, value.node).keywords['@id'] : undefined
    const code = typeof id === 'string' ? localName(id) : undefined
    if (code === to) has = true
    else if (code && codes.has(code)) ops.push({ op: 'remove', node: key, prop, value: value.key })
  }
  if (to && !has) {
    const term = vocabularyTerm(prop, to)
    const { value, nodes } = fragment({ '@id': term.uri, 'rdfs:label': [term.label] }, { node: key, prop })
    ops.push({ op: 'insert', node: key, prop, after: values.at(-1)?.key ?? null, value, nodes })
  }
  return ops
}

function vocabularyTerm(prop: string, code: string): { uri: string; label: string } {
  const list = prop === 'carrier' ? vocabularies.carriers : vocabularies.issuance
  const term = list.find((entry) => localName(entry.uri) === code)
  if (!term) throw new Error(`No ${prop} ${code} in the vocabularies`)
  return term
}

/** How a kind of resource uses a property: its tier and share, or undefined for one no form offers. */
export function usage(type: string, prop: string): Usage | undefined {
  if (never.has(prop)) return undefined
  const kind = measured[type]
  const instance = kind?.Instance[prop]?.share ?? 0
  const work = kind?.Work[prop]?.share ?? 0
  const share = Math.max(instance, work)
  const resource: Resource = work > instance ? 'Work' : 'Instance'
  const measuredTier: Tier = share >= thresholds.shown ? 'shown' : share >= thresholds.suggested ? 'suggested' : 'available'
  const force = forced[type]?.find((override) => override.prop === prop)
  if (!force) return { tier: measuredTier, share, resource }
  return { tier: force.tier, share, resource, override: { measured: measuredTier, reason: force.reason } }
}

/** The hand corrections for a kind of resource, in the order the overrides file gives them. */
export function overridesFor(type: string): readonly Override[] {
  return forced[type] ?? []
}

/**
 * The share of a kind of resource's records that use a property with one kind
 * of node, such as identifiedBy with an Isbn; undefined where it isn't measured.
 */
export function kindShare(type: string, prop: string, cls: string): number | undefined {
  const kind = measured[type]
  const shares = [kind?.Instance[prop]?.kinds?.[cls], kind?.Work[prop]?.kinds?.[cls]].filter(
    (share): share is number => share !== undefined,
  )
  return shares.length > 0 ? Math.max(...shares) : undefined
}

/** The properties a kind of resource shows or suggests, most used first. */
export function guidedProperties(type: string): { prop: string; usage: Usage }[] {
  const kind = measured[type]
  if (!kind) return []
  const props = new Set([...Object.keys(kind.Instance), ...Object.keys(kind.Work), ...overridesFor(type).map((override) => override.prop)])
  return [...props]
    .flatMap((prop) => {
      const found = usage(type, prop)
      return found && found.tier !== 'available' ? [{ prop, usage: found }] : []
    })
    .toSorted((a, b) => b.usage.share - a.usage.share)
}

function typesOf(doc: Doc, key: Key): string[] {
  const type = getNode(doc, key).keywords['@type']
  if (typeof type === 'string') return [type]
  return Array.isArray(type) ? type.filter((t): t is string => typeof t === 'string') : []
}

/** The local names of what a property links to: "mono" for .../issuance/mono. */
function linksOf(doc: Doc, key: Key, prop: string): string[] {
  return (getNode(doc, key).props[prop] ?? []).flatMap((value) => {
    const id = 'node' in value ? getNode(doc, value.node).keywords['@id'] : 'literal' in value ? value.literal : undefined
    return typeof id === 'string' ? [localName(id)] : []
  })
}

function localName(name: string): string {
  return name.replace(/\/+$/, '').split(/[/#:]/).pop() ?? name
}
